def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        return float(min(budget, max(8.0, DAILY_SALARY * 0.22)))

    pressure_bids = []
    urgent_bids = []
    weak_opp_count = 0
    rich_opp_count = 0

    for opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        prev_bid = prev.get('bid')
        if prev_bid is not None:
            pressure_bids.append(float(prev_bid))
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_bids.append(float(prev_bid))
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            weak_opp_count += 1
        if opp.get('budget', 0) >= 700:
            rich_opp_count += 1

    highest_prev = max(pressure_bids) if pressure_bids else 0.0
    urgent_prev = max(urgent_bids) if urgent_bids else highest_prev

    scarcity = float(WATER_REQ) / max(float(supply), 1.0)
    tight_supply = supply <= 17
    very_tight = supply <= 15

    must_win = hp <= 2 or no_water >= 2
    should_win = hp <= 4 or no_water >= 1

    if must_win:
        target = max(urgent_prev + 2.0, DAILY_SALARY * 0.96)
        if very_tight:
            target = max(target, DAILY_SALARY * 1.08)
        return float(min(budget, target))

    if should_win:
        target = max(urgent_prev + 1.5, highest_prev * 0.92, DAILY_SALARY * 0.78)
        if tight_supply:
            target = max(target, DAILY_SALARY * 0.9)
        return float(min(budget, target))

    if very_tight:
        target = max(highest_prev + 1.0, DAILY_SALARY * 0.72)
    elif tight_supply:
        target = max(highest_prev * 0.82, DAILY_SALARY * 0.56)
    else:
        target = DAILY_SALARY * 0.28
        if highest_prev > 0:
            target = min(target, highest_prev * 0.45)

    if weak_opp_count >= 2 and hp >= 6:
        target *= 0.85
    if rich_opp_count >= 2 and tight_supply:
        target = max(target, DAILY_SALARY * 0.68)
    if day >= 8 and hp >= 6:
        target *= 0.9

    reserve_floor = 0.0
    days_left = max(0, 10 - int(day))
    if days_left >= 2 and hp >= 5:
        reserve_floor = min(budget * 0.55, DAILY_SALARY * 2.2)
    spend_cap = max(0.0, budget - reserve_floor)
    if spend_cap <= 0:
        spend_cap = min(budget, DAILY_SALARY * 0.35)

    bid = min(target, spend_cap)
    bid = max(0.0, min(budget, bid))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # If no opponents, bid minimally to secure water
    if not alive_opponents:
        return min(my_status['budget'], 1.0) if my_status['budget'] > 0 else 0.0

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Strategy based on opponent's previous bids and my health
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        # If opponents were very aggressive yesterday (e.g., bidding >= 85% of daily salary)
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if my_status['hp'] > 3: # If healthy, conserve budget and let others fight for high bids
                return min(my_status['budget'], DAILY_SALARY * 0.3)
            else: # If HP is low, bid aggressively to survive
                return min(my_status['budget'], DAILY_SALARY * 0.95)
        else: # Opponents were not extremely aggressive, bid competitively
            # Bid at least 50% of salary, or slightly more than highest previous bid
            return min(my_status['budget'], max(DAILY_SALARY * 0.5, highest_prev_bid + 1.5))

    # If no yesterday bids (e.g., first day or opponents were not active/died)
    # Or if yesterday_bids list is empty (no trace for alive opponents)
    if my_status['hp'] <= 2: # Critical HP, bid high to survive
        return min(my_status['budget'], DAILY_SALARY * 0.9)

    # Default bid for healthy state or early days with no strong signals
    return min(my_status['budget'], DAILY_SALARY * 0.55)

